------------ import ------------
local UIModule = CS.Engine.UI.UIModule
local ActionUtils = import('Game.UI.FightReady.UIMainChapter.ActionUtils')
local CountDownTime = 2592000 --30 * 86400 30天的秒数
local CDTimerModule = CS.Engine.Modules.CDTimerModule
local BehaviourAction = CS.Engine.Lib.BehaviourAction
local KTool = CS.Engine.Lib.KTool
------------ import ------------

---@class UIActionPromptUpItemNode
---@field Env                            UIActionPromptUpItemNode
---@field controller                        Engine.Modules.LuaBehaviour | Engine.UI.UILuaDialog
---@field PromptUpItem                    UnityEngine.RectTransform
---@field Root                            UnityEngine.RectTransform
---@field MaskText                        UnityEngine.RectTransform
---@field TxtDesc                        UnityEngine.RectTransform
local UIActionPromptUpItemNode = Class("UIActionPromptUpItemNode")
function UIActionPromptUpItemNode:__init(handleEvent)
    self.handleEvent = checkBool(handleEvent)
    self.handler = nil
    
    self._imgGetW = 0  --旧代码 
    
    self.txtWidth = 0
    self.maskWidth = 0  --最大的x移动范围   目前按中心anchors和中心pivot计算
    self.moveSpeed = 30
    self.offsetY = 0
    self.maxX = 0

    self.stopTime = 0 --移动到最大距离后的停留时间
    self.timer = self.stopTime
end

---@private
function UIActionPromptUpItemNode:RefreshParams()
    self.txtWidth = self.TxtDesc.rect.width * self.TxtDesc.localScale.x
    self.maskWidth = self.MaskText.rect.width
    if self.maskWidth > self.txtWidth then
        self.maxX = 0
    else
        self.maxX = self.maskWidth * 0.5 + self.txtWidth * 0.5 + self._imgGetW
    end
    
    self.offsetY = self.TxtDesc.anchoredPosition.y
end

function UIActionPromptUpItemNode:__delete()
    self.handler = nil
end

function UIActionPromptUpItemNode:Awake()
end

function UIActionPromptUpItemNode:AddListener()
    if self.handler then
        Events.RemoveListener(Constants.EventNames.PVP_LADDER_TICK, self.handler)
        self.handler = nil
    end
    self.handler = Events.AddListener(Constants.EventNames.PVP_LADDER_TICK, function(countdown)
        if isNull(self.TxtDesc) then
            return
        end
        ---处理pvp刷新事情
        xTry(function()
            if countdown == 0 then
                ---倒计时已经结束了
                CfUtils.SetActive(self.controller.gameObject, false)
            else
                CfUtils.FillText(self.TxtDesc, localize('天梯竞技场进行中...距离结束: _time_', { _time_ = second_toHHMMSS(checkNumber(countdown)) }))
                CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(self.TxtDesc)
                self:RefreshParams()
            end
        end)
    end)
end

function UIActionPromptUpItemNode:Start()
    if GameUtils.IsTh() then
        self.TxtDesc:GetComponent(typeof(CS.UnityEngine.UI.Text)).textAutoAdjustable = false
    end 

    self:RefreshParams()
    self._behaviourAction = KTool.GetOrAddComponent(self.MaskText.gameObject, typeof(BehaviourAction))
    if self._behaviourAction then
        self._behaviourAction.UpdateAction = function()
            self:Update()
        end
    end
end

function UIActionPromptUpItemNode:Update()
    if self.maxX > 0 then
        if self.timer > 0 then
            self.timer = self.timer - CS.UnityEngine.Time.deltaTime
            return
        end

        local newX = self.TxtDesc.transform.anchoredPosition.x - (CS.UnityEngine.Time.deltaTime * self.moveSpeed)
        if math.abs(newX) >= self.maxX then
            self.timer = self.stopTime
            self.TxtDesc.transform.anchoredPosition = Vector3(self.maxX, self.offsetY, 0)
        else
            self.TxtDesc.transform.anchoredPosition = Vector3(newX, self.offsetY, 0)
        end
    end
end


function UIActionPromptUpItemNode:Refresh(str, isTrue)
    local offsetY = self.TxtDesc.anchoredPosition.y
    self.TxtDesc.transform.anchoredPosition = Vector3(0, offsetY, 0)
    if isTrue and self._imgGetW then
        self._imgGetW = self.ImgGet.transform.rect.width
    else
        self._imgGetW = 0
    end
    CfUtils.FillText(self.TxtDesc, checkString(str))
    CS.UnityEngine.UI.LayoutRebuilder.ForceRebuildLayoutImmediate(self.TxtDesc)
    self:RefreshParams()
end

function UIActionPromptUpItemNode:OnDestroy()
    if not isNull(self._behaviourAction) then
        self._behaviourAction.UpdateAction = nil
    end
    if self.handler then
        Events.RemoveListener(Constants.EventNames.PVP_LADDER_TICK, self.handler)
    end
    self.handler = nil
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return UIActionPromptUpItemNode